import sympy
from sympy import *

def pre_condition_0(delta:sympy.Rational):
	#delta >= 31/16

	pre_cond = GreaterThan(Symbol('delta'), Rational(31, 16))

	eval = pre_cond.subs( { 'delta':delta })

	if eval==True:
		assert eval!=False
		return True
	return False


def pre_condition_1(delta:sympy.Rational):
	#delta >= 1

	pre_cond = GreaterThan(Symbol('delta'), Integer(1))

	eval = pre_cond.subs( { 'delta':delta })

	if eval==True:
		assert eval!=False
		return True
	return False


